  3	final class BellmanFord {
  4	    private static final int EDGE_WIDTH = 3;
  5	    private static final int INF = 100_000_000;
  6	    private static final int[] NEGATIVE_CYCLE_RESULT = {-1};
  7	
  8	    private BellmanFord() {
  9	    }
 10	
 11	    static int[] bellmanFord(int vertices, int[][] edgeData, int source) {
 12	        validateInput(vertices, edgeData, source);
 13	        return bellmanFord(vertices, toEdges(vertices, edgeData), source);
 14	    }
 15	
 16	    private static int[] bellmanFord(int vertices, Edge[] edges, int source) {
 17	        int[] distances = initializeDistances(vertices, source);
 18	
 19	        for (int pass = 0; pass < vertices - 1; pass++) {
 20	            boolean updated = false;
 21	
 22	            for (Edge edge : edges) {
 23	                updated |= relax(edge, distances);
 24	            }
 25	
 26	            if (!updated) {
 27	                return distances;
 28	            }
 29	        }
 30	
 31	        if (hasNegativeCycle(edges, distances)) {
 32	            return NEGATIVE_CYCLE_RESULT;
 33	        }
 34	
 35	        return distances;
 36	    }
 37	
 38	    private static void validateInput(int vertices, int[][] edgeData, int source) {
 39	        if (vertices <= 0) {
 40	            throw new IllegalArgumentException("vertices must be positive");
 41	        }
 42	        if (source < 0 || source >= vertices) {
 43	            throw new IllegalArgumentException("source must be within the vertex range");
 44	        }
 45	        if (edgeData == null) {
 46	            throw new IllegalArgumentException("edges must not be null");
 47	        }
 48	    }
 49	
 50	    private static int[] initializeDistances(int vertices, int source) {
 51	        int[] distances = new int[vertices];
 52	        Arrays.fill(distances, INF);
 53	        distances[source] = 0;
 54	        return distances;
 55	    }
 56	
 57	    private static boolean relax(Edge edge, int[] distances) {
 58	        if (distances[edge.from] == INF) {
 59	            return false;
 60	        }
 61	
 62	        int candidateDistance = distances[edge.from] + edge.weight;
 63	        if (candidateDistance >= distances[edge.to]) {
 64	            return false;
 65	        }
 66	
 67	        distances[edge.to] = candidateDistance;
 68	        return true;
 69	    }
 70	
 71	    private static boolean hasNegativeCycle(Edge[] edges, int[] distances) {
 72	        for (Edge edge : edges) {
 73	            if (distances[edge.from] != INF
 74	                    && distances[edge.from] + edge.weight < distances[edge.to]) {
 75	                return true;
 76	            }
 77	        }
 78	        return false;
 79	    }
