 81	    private static Edge[] toEdges(int vertices, int[][] edgeData) {
 82	        Edge[] edges = new Edge[edgeData.length];
 83	        for (int i = 0; i < edgeData.length; i++) {
 84	            int[] edge = edgeData[i];
 85	            if (edge == null || edge.length != EDGE_WIDTH) {
 86	                throw new IllegalArgumentException("each edge must contain exactly 3 integers");
 87	            }
 88	
 89	            int from = edge[0];
